<script setup lang="ts">import type {Cell} from '../types/domain';import {number} from '../utils/format';defineProps<{cells:Cell[];a:string[];b:string[]}>();</script><template><section class="cell-matrix"><div class="section-heading"><h2>处理格实验记录</h2><span>温度 × 釉层 / MPa，n=独立试片</span></div><div class="table-wrap"><table><thead><tr><th>釉层</th><th v-for="level in a" :key="level">{{level}}°C</th></tr></thead><tbody><tr v-for="glaze in b" :key="glaze"><th>{{glaze}}</th><td v-for="temp in a" :key="temp"><template v-for="c in cells" :key="c.id??temp+glaze"><template v-if="c.temperature===temp&&c.glaze===glaze"><b>{{number(c.mean,2)}}</b><small>n={{c.n}} 独立试片</small><small v-if="c.raw_reading_count!==undefined&&c.raw_reading_count!==c.n">原始读数 {{c.raw_reading_count}} 条（含复测，已按试片均值聚合）</small></template></template></td></tr></tbody></table></div></section></template>
